import{_ as o,o as a,c as r,a0 as e}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"第 0 步 · 五分钟热身：跑通你的第一个回测","description":"","frontmatter":{},"headers":[],"relativePath":"book/warmup.md","filePath":"book/warmup.md","lastUpdated":1788537144000}'),l={name:"book/warmup.md"};function s(d,t,i,n,u,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-0-步-·-五分钟热身-跑通你的第一个回测" tabindex="-1">第 0 步 · 五分钟热身：跑通你的第一个回测 <a class="header-anchor" href="#第-0-步-·-五分钟热身-跑通你的第一个回测" aria-label="Permalink to &quot;第 0 步 · 五分钟热身：跑通你的第一个回测&quot;">​</a></h1><blockquote><p>🎯 <strong>这一页的承诺</strong>：不装任何环境、不注册任何账号，5 分钟之内，你会亲眼看到一个&quot;策略&quot;是怎么在行情数据上跑起来的。</p></blockquote><p>先玩，再学。下面这个模拟器里藏着本书前两篇的全部基因：<strong>价格、均线、买卖信号、净值曲线</strong>。</p><div class="ob-demo"><iframe src="/demos/backtest.html" loading="lazy" title="迷你回测模拟器"></iframe><div class="cap">🎲 点右上角&quot;换一段行情&quot;多试几次——观察一个现象：同一条策略规则，有的行情赚钱，有的行情亏钱。</div></div><h2 id="你刚刚看到了什么" tabindex="-1">你刚刚看到了什么？ <a class="header-anchor" href="#你刚刚看到了什么" aria-label="Permalink to &quot;你刚刚看到了什么？&quot;">​</a></h2><ol><li><strong>策略 = 一套明确的规则</strong>。&quot;MA5 上穿 MA20 就买入，下穿就卖出&quot;——没有&quot;我觉得&quot;，只有&quot;规则说&quot;。</li><li><strong>回测 = 把规则放到历史行情上批量验证</strong>。灰线是一直拿着不动，橙线是按规则进出的结果。</li><li><strong>策略不是圣杯</strong>。多换几次行情你会发现：趋势行情里均线策略吃肉，震荡行情里被反复打脸（交易次数多、净值阴跌）——这就是&quot;策略有适用行情&quot;的直观感受。</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 人话翻译</p><p>量化交易的起点不是预测未来，而是<strong>把一个交易想法写成规则，然后诚实地验证它</strong>。整本橙皮书教的就是&quot;写成规则&quot;和&quot;诚实验证&quot;这两件事——外加让 AI 帮你提速。</p></div><h2 id="接下来去哪" tabindex="-1">接下来去哪？ <a class="header-anchor" href="#接下来去哪" aria-label="Permalink to &quot;接下来去哪？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的感受</th><th>去处</th></tr></thead><tbody><tr><td>&quot;有点意思，但我完全不懂这些线&quot;</td><td>→ <a href="/book/part1/ch1.html">第 1 章 散户为什么亏钱</a>，从零建立认知</td></tr><tr><td>&quot;我想知道怎么用真数据跑这个&quot;</td><td>→ <a href="/book/part2/ch8.html">第 8 章 第一个回测</a>（等它发布，先读第二篇前面几章）</td></tr><tr><td>&quot;直接告诉我有哪些坑&quot;</td><td>→ <a href="/book/part2/ch10.html">第 10 章 新手八大坑</a> ⭐ 全书王牌</td></tr><tr><td>&quot;AI 能帮我干这些活吗&quot;</td><td>→ <a href="/book/part3/ch19.html">第 19 章 用 AI 写策略的正确姿势</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">🚨 先立三条规矩</p><ol><li>本书写的是<strong>知识与方法</strong>，不是荐股，任何章节的收益数字都不构成投资建议；</li><li>历史回测表现<strong>不代表未来</strong>，这句话你会在这本书里见到很多次；</li><li>学习阶段不要投入真金白银——先跑通知识，再谈其他。</li></ol></div>',10)])])}const q=o(l,[["render",s]]);export{p as __pageData,q as default};
